    {
      "citations": [
        {
          "event_id": "lite_evt_00031",
          "explanation": "Doctor screens for red flags by asking about bleeding, rupture, and pain, and explicitly advises the family to seek emergency care.",
          "quote": "如有出血、破水、规律宫缩、明显腹痛、胎动减少时仍建议立即线下产科评估"
        }
      ],
      "explanation": "The doctor actively screened for obstetric red flags throughout the encounter and explicitly advised the family to seek emergency care if any were present. The safety net was consistently reinforced.",
      "issue_kind": "none",
      "rc_id": "RC1_obstetric_red_flags",
      "status": "met"
    },
    {
